package org.tsc.dispatch.config;

/** Holds the documented YAML template written on first start. */
public final class ConfigTemplate {

	private ConfigTemplate() {
	}

	public static final String YAML = "# ==============================================================================\n# tsc-dispatch configuration  (schema version 1)\n#\n# One file drives the whole service. Sections map 1:1 to the seven design areas:\n#   tsc / bridge / rcon / dimensions / network_scale / dispatch / platform_allow\n# Every value below is the built-in default; delete what you do not need.\n# ==============================================================================\n\nservice:\n  name: tsc-dispatch\n  # instance_id is generated at boot and echoed in logs and /v1/status\n  instance_id: \"\"\n\nadmin:\n  enabled: true\n  host: 127.0.0.1          # bind loopback unless a reverse proxy fronts it\n  port: 8787\n  token: \"\"                # non-empty enables \"Authorization: Bearer <token>\"\n\n# ------------------------------------------------------------------------------\n# 1. TSC / MTR version and the port the simulator actually listens on\n# ------------------------------------------------------------------------------\ntsc:\n  base_url: http://127.0.0.1:8888\n  timeout_ms: 2500\n  retry_count: 2\n  # default dimension index used when the dimensions list is omitted\n  dimension: 0\n\n  version:\n    # Operator declared version of the running mod, e.g. \"4.0.2\".\n    # The HTTP surface does not publish it, so it must be stated here; the API\n    # fingerprint below is what actually protects against breakage.\n    declared: \"\"\n    min: \"4.0.0\"\n    max: \"\"                # empty = no upper bound\n    strict: false          # true = refuse to start when out of range or unknown\n\n  port_discovery:\n    # The mod falls back to a free port when the configured one is taken, so the\n    # service probes a range and reports the port it actually reached.\n    enabled: true\n    range_start: 8888\n    range_end: 8898\n\n# ------------------------------------------------------------------------------\n# 2. Control bridge (the only write channel that can address individual trains)\n#    auto   = use it when the probe succeeds, otherwise fall through\n#    bridge = require it (start degraded if absent)\n#    rcon   = never probe the bridge\n#    observe= read only, never write\n# ------------------------------------------------------------------------------\nbridge:\n  enabled: true\n  mode: auto\n  form: http               # http | mod | script  (informational, used in reports)\n  base_url: http://127.0.0.1:8889\n  protocol: 1\n  timeout_ms: 2000\n  probe_interval_ms: 15000\n  offline_after_failures: 3\n  auth_token: \"\"           # sent as Authorization: Bearer\n  require_vehicle_telemetry: true\n  # command kinds the bridge must advertise for the service to consider it usable\n  features_required: [set_platform]\n\n# ------------------------------------------------------------------------------\n# 3. RCON fallback\n# ------------------------------------------------------------------------------\nrcon:\n  enabled: true\n  host: 127.0.0.1\n  port: 25575\n  password: \"\"             # empty disables RCON even when enabled is true\n  timeout_ms: 3000\n  # when to fall back to RCON: bridge_offline | bridge_reject | command_timeout | manual\n  fallback_on: [bridge_offline, bridge_reject, command_timeout]\n  commands:\n    refresh_depot_routes: \"mtr generatePath {depot}\"\n    instant_deploy: \"mtr instantDeploy {depot}\"\n    clear_depot: \"mtr clearVehicles {depot}\"\n\nactuator:\n  mode: auto               # auto | bridge | rcon | dry-run\n  allow_advisory_only: true\n\n# ------------------------------------------------------------------------------\n# 4. Dimensions. index is the value sent as ?dimension= and follows the order\n#    the host server loaded its worlds - never guess it from the id.\n# ------------------------------------------------------------------------------\ndimensions:\n  - id: minecraft:overworld\n    index: 0\n    enabled: true\n  - id: minecraft:the_nether\n    index: 1\n    enabled: false\n  - id: minecraft:the_end\n    index: 2\n    enabled: false\n\n# ------------------------------------------------------------------------------\n# 5. Network scale and adaptive polling\n# ------------------------------------------------------------------------------\nnetwork_scale:\n  total_stations: 0        # 0 = unknown / discover at runtime\n  total_platforms: 0\n  total_routes: 0\n  total_depots: 0\n  max_trains: 30\n  polling_interval_ms: 2000        # baseline, used when adaptive is false\n  static_polling_interval_ms: 30000\n  adaptive: true\n  polling_min_ms: 500\n  polling_max_ms: 10000\n  # first tier whose max_trains covers the configured/observed train count wins\n  tiers:\n    - max_trains: 10\n      polling_interval_ms: 1000\n    - max_trains: 40\n      polling_interval_ms: 2000\n    - max_trains: 100000\n      polling_interval_ms: 4000\n\n# ------------------------------------------------------------------------------\n# 6. Objective and hard constraints\n#    strategy presets: on_time | min_waiting | balanced\n# ------------------------------------------------------------------------------\ndispatch:\n  strategy: balanced\n  # Explicit weights override the preset; blank/omitted inherits from the preset.\n  weights:\n    travel:\n    occupancy:\n    wait:\n    depot:\n    deviation:\n\n  constraints:\n    # hard cap on how many trains may be heading to / parked in one depot\n    depot_capacity_limit: 0        # 0 = unlimited\n    depot_capacity: {}             # per depot override, e.g. { \"Central Depot\": 5 }\n    max_hold_seconds: 0            # 0 = never hold a train on purpose\n    blocked_penalty_seconds: 900   # soft penalty that keeps every plan feasible\n    # multiplier applied to a route's effective priority (higher = wins conflicts)\n    route_priority: {}             # e.g. { \"A\": 2.0, \"1000000000000002\": 1.5 }\n\n  dedup_window_seconds: 600\n  command_ttl_seconds: 45\n  max_attempts: 3\n  retry_backoff_ms: 250\n  lease_ttl_seconds: 120\n\ntrigger:\n  approach_lead_seconds: 120\n  platform_headway_seconds: 90\n  cooldown_seconds: 30\n  return_after_seconds: 5400\n  return_at_local_time: \"\"         # \"02:00-04:30\", supports crossing midnight\n\nplanner:\n  estimate_speed_mps: 18.0\n  depot_access_seconds: 150\n\n# ------------------------------------------------------------------------------\n# 7. Platform allow-set\n#    default: allow | deny\n#    A rule matches on route (number, hex id or \"*\") and station (hex id or \"*\").\n#    deny=false -> allow-list; deny=true -> deny-list. First match collection wins,\n#    a platform is allowed when it is in an allow-list and in no deny-list.\n# ------------------------------------------------------------------------------\nplatform_allow:\n  default: allow\n  rules:\n    - route: \"A\"\n      station: \"0000000000000004\"\n      platforms: [\"0000000000000041\", \"0000000000000042\"]\n    - route: \"*\"\n      station: \"0000000000000001\"\n      platforms: [\"0000000000000011\", \"0000000000000012\"]\n\n# optional manual platform catalogue: the stock API only reveals platforms that\n# already have a scheduled arrival, so declare idle alternatives here\ncatalogue:\n  platforms: \"\"\n\nstate:\n  dir: state\n\nlog:\n  level: INFO\n  file: \"\"\n";
}
